You are a web developer. Fix the bug in the following code.

BUG DESCRIPTION: A counter component uses a local increment/decrement mutation instead of updating React state, so the display never changes.

CODE:
import React, { useState } from 'react';

export default function Counter() {
  const [count] = useState(0);

  const increment = () => {
    let nextCount = count;
    nextCount++;
  };

  const decrement = () => {
    if (count === 0) {
      return;
    }

    let nextCount = count;
    nextCount--;
  };

  return (
    <div>
      <div data-testid="count">{count}</div>
      <button type="button" onClick={increment}>
        Increment
      </button>
      <button type="button" onClick={decrement}>
        Decrement
      </button>
    </div>
  );
}

